            </div>
            <Text style={{ color: '#6b7280', fontSize: 13, fontWeight: 500 }}>Tỷ lệ lấp đầy</Text>
            <Title level={3} style={{ margin: '4px 0 0', fontWeight: 700 }}>{Math.min(100, totalBookings * 10)}%</Title>
