            <div style={{ padding: 16, backgroundColor: '#f5f3ff', border: '1px solid #ddd6fe', borderRadius: 12, marginBottom: 24 }}>
              <div style={{ fontWeight: 600, color: '#5b21b6', marginBottom: 8 }}>Phân tích hệ thống:</div>
